"""Data nodes shared by the parsers, evaluator, and writers."""
import copy
import math
import re


class YQError(Exception):
    pass


class Node:
    def __init__(self, value=None, kind=None, tag=None, raw=None, style=''):
        if kind is None:
            kind = 'map' if isinstance(value, dict) else 'seq' if isinstance(value, list) else 'scalar'
        self.kind = kind
        self.value = value
        if kind == 'map':
            self.value = [(scalar(str(k)), from_python(v)) for k, v in value.items()] if isinstance(value, dict) else (value or [])
        elif kind == 'seq':
            self.value = [from_python(v) for v in (value or [])]
        self.tag = tag if tag is not None else ('!!map' if kind == 'map' else '!!seq' if kind == 'seq' else tag_for(value))
        self.raw = raw if raw is not None else raw_for(value) if kind == 'scalar' else ''
        self.style = style
        self.explicit_tag = False
        self.anchor = ''
        self.alias_target = None
        self.head = ''
        self.line_comment = ''
        self.foot = ''
        self.header = ''
        self.line = 0
        self.column = 0
        self.parent = None
        self.key = None
        self.is_key = False
        self.doc = 0
        self.file_index = 0
        self.filename = ''
        self.synthetic = True

    def clone(self):
        # Parent links aren't part of the value and should never clone the whole document.
        memo = {}
        def rec(n):
            if id(n) in memo:
                return memo[id(n)]
            r = Node()
            memo[id(n)] = r
            r.__dict__.update(n.__dict__)
            r.parent = None
            if n.kind == 'map':
                r.value = [(rec(k), rec(v)) for k, v in n.value]
            elif n.kind == 'seq':
                r.value = [rec(v) for v in n.value]
            if n.alias_target is not None:
                r.alias_target = n.alias_target
            return r
        r = rec(self)
        link(r)
        return r

    def deref(self):
        n, seen = self, set()
        while n.kind == 'alias' and n.alias_target is not None and id(n) not in seen:
            seen.add(id(n))
            n = n.alias_target
        return n

    def items(self):
        n = self.deref()
        return n.value if n.kind == 'map' else []

    def children(self, keys=False):
        if self.kind == 'map':
            return [x for pair in self.value for x in pair] if keys else [v for k,v in self.value]
        if self.kind == 'seq':
            return self.value
        return []

    def get(self, key):
        key = key if isinstance(key, Node) else scalar(key)
        if self.kind == 'map':
            for k, v in self.value:
                if k.raw == key.raw:
                    return v
        return None

    def put(self, key, val):
        key = key if isinstance(key, Node) else scalar(key)
        for i, (k, v) in enumerate(self.value):
            if k.raw == key.raw:
                self.value[i] = (k, val)
                attach(self, k, val)
                return
        self.value.append((key, val))
        attach(self, key, val)


def tag_for(v):
    if v is None: return '!!null'
    if isinstance(v, bool): return '!!bool'
    if isinstance(v, int): return '!!int'
    if isinstance(v, float): return '!!float'
    return '!!str'


def raw_for(v):
    if v is None: return 'null'
    if isinstance(v, bool): return 'true' if v else 'false'
    if isinstance(v, float):
        if math.isnan(v): return '.nan'
        if math.isinf(v): return '.inf' if v > 0 else '-.inf'
        if v == int(v): return str(int(v))
        s = repr(v)
        if 'e' in s:
            a,b=s.split('e')
            s = a + 'e' + ('+' if int(b)>=0 else '-') + str(abs(int(b)))
        return s
    return str(v)


def scalar(v=None, raw=None, style='', tag=None):
    return Node(v, raw=raw, style=style, tag=tag)


def sequence(vals=None, style=''):
    r = Node(vals or [],kind='seq',style=style)
    link(r)
    return r


def mapping(vals=None, style=''):
    r = Node(vals or [], kind='map', style=style)
    link(r)
    return r


def from_python(v):
    if isinstance(v, Node): return v
    return Node(v)


def attach(parent, key, val):
    val.parent = parent
    val.key = key
    val.is_key = False
    if isinstance(key, Node):
        key.parent = parent
        key.key = None
        key.is_key = True


def link(n, doc=None, fi=None, filename=None, seen=None):
    if seen is None: seen=set()
    if id(n) in seen:return
    seen.add(id(n))
    if doc is not None:n.doc=doc
    if fi is not None:n.file_index=fi
    if filename is not None:n.filename=filename
    if n.kind=='map':
        for k,v in n.value:
            attach(n,k,v)
            link(k,doc,fi,filename,seen); link(v,doc,fi,filename,seen)
    elif n.kind=='seq':
        for i,v in enumerate(n.value):
            attach(n,i,v); link(v,doc,fi,filename,seen)


def origin(n, ref, recursive=False):
    n.doc=ref.doc
    n.file_index=ref.file_index
    n.filename=ref.filename
    if recursive: link(n,n.doc,n.file_index,n.filename)
    return n


def value(n, seen=None):
    if seen is None:seen=set()
    if id(n) in seen:return None
    seen.add(id(n))
    if n.kind=='alias':return value(n.deref(),seen)
    if n.kind=='map':return {k.raw:value(v,seen.copy()) for k,v in n.value}
    if n.kind=='seq':return [value(v,seen.copy()) for v in n.value]
    if n.tag=='!!str' or not n.tag.startswith('!!'):return n.raw
    if n.tag=='!!null':return None
    if n.tag=='!!bool':return n.raw.lower()=='true'
    if n.tag=='!!int':
        try:return int_value(n.raw)
        except Exception:return n.value
    if n.tag=='!!float':
        try:return float_value(n.raw)
        except Exception:return n.value
    return n.raw


def truth(n):
    n=n.deref()
    return n.tag!='!!null' and not (n.tag=='!!bool' and n.raw.lower()=='false')


def int_value(s):
    s=s.replace('_','')
    if re.match(r'^[+-]?0[xXoObB]',s):return int(s,0)
    if re.match(r'^[+-]?0[0-7]+$',s):return int(s,8)
    return int(s,10)


def float_value(s):
    s=s.replace('_','').lower()
    if s in ('.inf','+.inf'):return float('inf')
    if s=='-.inf':return float('-inf')
    if s=='.nan':return float('nan')
    return float(s)


def resolve_plain(s, key=False):
    if s in ('null','Null','NULL','~',''):return scalar(None,raw=s)
    if s in ('true','True','TRUE','false','False','FALSE'):return scalar(s.lower()=='true',raw=s)
    if s=='<<' and key:return scalar(s,tag='!!merge')
    ss=s.replace('_','')
    if re.match(r'^[+-]?(?:0[xX][0-9a-fA-F]+|0[oO][0-7]+|0[bB][01]+|[0-9]+)$',ss):
        try:return scalar(int_value(s),raw=s)
        except ValueError:pass
    if re.match(r'^[+-]?(?:(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?|\.inf|\.Inf|\.INF)$',ss) or ss in ('.nan','.NaN','.NAN'):
        try:return scalar(float_value(s),raw=s)
        except ValueError:pass
    if re.match(r'^\d{4}-\d\d-\d\d(?:[Tt ]|$)',s):return scalar(s,tag='!!timestamp')
    return scalar(s)


def node_path(n):
    path=[];seen=set()
    while n.parent is not None and id(n) not in seen:
        seen.add(id(n))
        if n.key is not None:
            path.append(n.key.clone() if isinstance(n.key,Node) else scalar(n.key))
        n=n.parent
    path.reverse()
    return path


def walk(n, keys=False, seen=None):
    if seen is None:seen=set()
    if id(n) in seen:return
    seen.add(id(n));yield n
    for child in n.children(keys):yield from walk(child,keys,seen)


def deep_equal(a,b):
    a=a.deref();b=b.deref()
    if a.kind!=b.kind:return False
    if a.kind=='map':
        return len(a.value)==len(b.value) and all((b.get(k) is not None and deep_equal(v,b.get(k))) for k,v in a.value)
    if a.kind=='seq':return len(a.value)==len(b.value) and all(deep_equal(x,y) for x,y in zip(a.value,b.value))
    return a.tag==b.tag and a.raw==b.raw
PY"}

