    if s!=s.strip():return 'single'
    if s[0] in '!&*{}[],#|>@`"\'%':return 'single'
    if s in ('-','?',':','---','...') or s.startswith(('- ', '? ', ': ')):return 'single'
    if re.search(r':(?:\s|$)|(?:^|\s)#',s):return 'single'
