        if n.header and header:out=n.header.rstrip('\n').split('\n')+out
        return '\n'.join(out)+'\n'


def dump_yaml(n,indent=2,pretty=False,compact=False,unwrap=False,colors=False,header=True):
    return YAMLWriter(indent,pretty,compact,colors).dump(n,unwrap,header)
