def detect_format(filename):
    ext=os.path.splitext(filename)[1].lower().lstrip('.')
    if ext in ('yml','yaml'):return 'yaml'
    if ext in ('properties','props'):return 'props'
    if ext in FORMATS:return ext
    return 'yaml'


def json_node(obj):
    # JSON object pairs remain ordered and duplicate keys are retained.
    if isinstance(obj,JSONPairs):return mapping([(scalar(k),json_node(v)) for k,v in obj])
    if isinstance(obj,list):return sequence([json_node(v) for v in obj])
    return scalar(obj)


class JSONPairs(list):pass


def decode(text,fmt='yaml',opts=None):
    opts=opts or {};fmt=canonical(fmt)
    if fmt in ('yaml','auto'):return parse_yaml(text,opts.get('header_preprocess',True))
    if fmt=='kyaml':
        # The accepted relaxed JSON notation has trailing commas and unquoted keys.
        return parse_yaml(text,False)
    if fmt=='json':
        decoder=json.JSONDecoder(object_pairs_hook=JSONPairs)
        docs=[];pos=0
        while pos<len(text):
            while pos<len(text) and text[pos].isspace():pos+=1
            if pos==len(text):break
            try:obj,end=decoder.raw_decode(text,pos)
            except json.JSONDecodeError as e:
                ch=text[e.pos:e.pos+1]
                if not ch:raise YQError('unexpected EOF')
                if e.msg.startswith('Expecting property'):msg='looking for beginning of object key string'
                elif e.msg.startswith('Expecting value'):msg='looking for beginning of value'
                elif e.msg.startswith("Expecting ','"):msg='after object key:value pair'
                else:msg='in JSON input'
                raise YQError("invalid character '%s' %s"%(ch,msg))
            docs.append(json_node(obj));pos=end
        return docs or [scalar(None,raw='')]
    if fmt in ('csv','tsv'):
        delim=opts.get('csv_separator',',') if fmt=='csv' else '\t'
        try:rows=list(csv.reader(io.StringIO(text),delimiter=delim,strict=True))
        except csv.Error as e:raise YQError('parse error: '+str(e))
        rows=[r for r in rows if r]
        if not rows:return [sequence()]
        headers=rows[0];vals=[];auto=opts.get(fmt+'_auto_parse',True)
        for i,row in enumerate(rows[1:],2):
            if len(row)!=len(headers):raise YQError('record on line %d: wrong number of fields'%i)
            pairs=[]
            for k,s in zip(headers,row):
                if auto:
                    try:n=parse_yaml(s,False)[0]
                    except YQError:n=scalar(s)
                else:n=scalar(s)
                pairs.append((scalar(k),n))
            vals.append(mapping(pairs))
        return [sequence(vals)]
    if fmt=='props':return [decode_props(text)]
    if fmt=='ini':return [decode_ini(text)]
    if fmt=='xml':return [decode_xml(text,opts)]
    if fmt=='toml':return [decode_toml(text)]
    if fmt=='hcl':return [decode_hcl(text)]
    if fmt=='lua':return [decode_lua(text)]
    if fmt=='base64':
        try:return [scalar(base64.b64decode(text.replace('\n','').replace('\r',''),validate=True).decode('utf-8',errors='replace'))]
        except Exception:
            clean=text.replace('\n','').replace('\r','')
            bad=re.search(r'[^A-Za-z0-9+/=]',clean);i=bad.start() if bad else len(clean)-len(clean)%4
            raise YQError('illegal base64 data at input byte %d'%i)
    if fmt=='uri':
        invalid=re.search(r'%(?![0-9A-Fa-f]{2})',text)
        if invalid:raise YQError('invalid URL escape '+json.dumps(text[invalid.start():invalid.start()+3]))
        return [scalar(urllib.parse.unquote_plus(text))]
    if fmt=='shell':raise YQError('no support for shell input format')
    return []


def flatten_nodes(n,path=None):
    path=path or []
    n=n.deref()
    if n.kind=='map':
        for k,v in n.value:yield from flatten_nodes(v,path+[k.raw])
    elif n.kind=='seq':
        for i,v in enumerate(n.value):yield from flatten_nodes(v,path+[i])
    else:yield path,n


def encode(n,fmt='yaml',opts=None,unwrap=None):
    opts=opts or {};fmt=canonical(fmt)
    if fmt=='auto':fmt='yaml'
    if unwrap is None:unwrap=opts.get('unwrapScalar',fmt in ('yaml','props','ini','toml','hcl'))
    if fmt=='yaml':return dump_yaml(n,opts.get('indent',2),opts.get('prettyPrint',False),opts.get('yaml_compact_seq_indent',False),unwrap,opts.get('colors',False),not opts.get('no_doc',False))
    if fmt=='json':
        if unwrap and n.kind=='scalar':return n.raw+'\n'
        py=value(n)
        def check(obj):
            if isinstance(obj,float) and not math.isfinite(obj):raise YQError('json: unsupported value: '+('NaN' if math.isnan(obj) else '+Inf' if obj>0 else '-Inf'))
            if isinstance(obj,dict):
                for x in obj.values():check(x)
            elif isinstance(obj,list):
                for x in obj:check(x)
        check(py)
        indent=opts.get('indent',2)
        ret=json.dumps(py,ensure_ascii=False,separators=(',',':') if indent<=0 else (',',': '),indent=indent if indent>0 else None)
        # Go's writer leaves HTML characters alone, while escaping Unicode separators.
        ret=ret.replace('\u2028','\\u2028').replace('\u2029','\\u2029')
        return ret+'\n'
    if fmt=='kyaml':return encode_kyaml(n,opts)
    if fmt in ('csv','tsv'):return encode_csv(n,opts.get('csv_separator',',') if fmt=='csv' else '\t')
    if fmt=='props':
        if n.kind=='scalar' and unwrap:return n.raw+'\n'
        out=[]
        sep=opts.get('properties_separator',' = ')
        for path,v in flatten_nodes(n):
            key=''
            for part in path:
                if isinstance(part,int) and opts.get('properties_array_brackets'):key+='[%d]'%part
                else:key+=('.' if key else '')+str(part)
            def esc(s):return s.replace('\\','\\\\').replace('\n','\\n').replace('\r','\\r').replace('\t','\\t')
            key=esc(key).replace(' ','\\ ').replace(':','\\:').replace('=','\\=')
            if v.head:out.extend(normalized_comment(v.head).splitlines())
            out.append(key+sep+esc(v.raw))
        prefix=n.header if n.header and n.kind!='scalar' else ''
        if prefix:prefix='\n'.join(x for x in prefix.splitlines() if x.lstrip().startswith('#'))+'\n'
        return prefix+'\n'.join(out)+('\n' if out else '')
    if fmt=='shell':
        out=[];sep=opts.get('shell_key_separator','_')
        for path,v in flatten_nodes(n):
            key=sep.join(str(p) for p in path) if path else 'value'
            key=re.sub(r'[^A-Za-z0-9_]','_',key)
            if key and key[0].isdigit():key='_'+key
            s=v.raw
            if not re.fullmatch(r'[A-Za-z0-9_./-]*',s):s="'"+s.replace("'", "'\"'\"'")+"'"
            out.append(key+'='+s)
        return '\n'.join(out)+('\n' if out else '')
    if fmt=='xml':return encode_xml(n,opts)
    if fmt=='ini':return encode_ini(n,opts,unwrap)
    if fmt=='toml':return encode_toml(n,opts,unwrap)
    if fmt=='hcl':return encode_hcl(n,opts,unwrap)
    if fmt=='lua':return encode_lua(n,opts)
    if fmt=='base64':
        if n.tag!='!!str':raise YQError('cannot encode %s as base64, can only operate on strings'%n.tag)
        return base64.b64encode(n.raw.encode()).decode()+'\n'
    if fmt=='uri':
        if n.tag!='!!str':raise YQError('cannot encode %s as URI, can only operate on strings. Please first pipe through another encoding operator to convert the value to a string'%n.tag)
        return urllib.parse.quote_plus(n.raw,safe='')+'\n'
    raise YQError('unknown format '+fmt)


def encode_csv(n,delimiter):
    if n.kind!='seq':raise YQError('csv encoding only works for arrays, got: '+n.tag)
    if not n.value:return ''
    def cell(v):
        if v.kind=='scalar':return v.raw
        raise YQError('csv encoding only works for arrays of flat maps (string key => scalar value), got: '+v.tag)
    rows=[]
    if n.value[0].kind=='map':
        keys=[k for k,v in n.value[0].value];rows.append([k.raw for k in keys])
        for item in n.value:rows.append([cell(item.get(k)) if item.get(k) else '' for k in keys])
    elif n.value[0].kind=='seq':rows=[[cell(v) for v in row.value] for row in n.value]
    else:rows=[[cell(v) for v in n.value]]
    # encoding/csv quotes leading whitespace and carriage returns as well.
    def quote(s):
        if delimiter in s or '"' in s or '\n' in s or '\r' in s or (s and s[0].isspace()):return '"'+s.replace('"','""')+'"'
        return s
    return ''.join(delimiter.join(quote(c) for c in row)+'\n' for row in rows)


def property_unescape(s):
    def repl(m):
        g=m.group(1)
        if g.startswith('u'):
            try:return chr(int(g[1:],16))
            except Exception:return g
        return {'n':'\n','r':'\r','t':'\t','f':'\f'}.get(g,g)
    return re.sub(r'\\(u[0-9a-fA-F]{4}|.)',repl,s)


def set_nested(root,path,val):
    cur=root
    for i,k in enumerate(path):
        last=i==len(path)-1
        if cur.kind=='map':
            key=scalar(str(k));child=cur.get(key)
            if last:cur.put(key,val);return
            if child is None:
                child=sequence() if isinstance(path[i+1],int) else mapping();cur.put(key,child)
            cur=child
        elif cur.kind=='seq':
            try:idx=int(k)
            except Exception:idx=0
            if idx<0 or idx>100000:continue
            while len(cur.value)<=idx:cur.value.append(scalar())
            if last:cur.value[idx]=val;link(cur);return
            child=cur.value[idx]
            if child.tag=='!!null':
                child=sequence() if isinstance(path[i+1],int) else mapping();cur.value[idx]=child
            cur=child
        else:return


def decode_props(text):
    r=mapping();comments=[];first=True
    text=re.sub(r'\\\n[ \t]*','',text)
    for line in text.splitlines():
        s=line.strip()
        if not s or s.startswith(('#','!')):
            if s:comments.append('#'+s[1:])
            continue
        m=re.match(r'((?:\\.|[^:=\s])+)(?:\s*[:=]\s*|\s+)?(.*)$',s)
        if not m:continue
        key=property_unescape(m.group(1));val=scalar(property_unescape(m.group(2)))
        key=re.sub(r'\[([0-9]+)\]',r'.\1',key)
        path=[int(p) if p.isdigit() else p for p in key.split('.')]
        if first and comments:r.header='\n'.join(comments)+'\n';r.head='\n'.join(comments)
        elif comments:val.head='\n'.join(comments)
        set_nested(r,path,val);comments=[];first=False
    link(r);return r


def decode_ini(text):
    root=mapping();current=root;comments=[]
    for line in text.splitlines():
        s=line.strip()
        if not s:continue
        if s.startswith((';','#')):comments.append('#'+s[1:]);continue
        if s.startswith('[') and ']' in s:
            section=s[1:s.index(']')]
            if section=='DEFAULT':current=root;continue
            current=root.get(section)
            if current is None:current=mapping();root.put(section,current)
            if comments:current.head='\n'.join(comments);comments=[]
            continue
        m=re.match(r'([^=:\s]+)\s*[=:]\s*(.*)',s)
        if not m:raise YQError('key-value delimiter not found: '+s)
        k,v=m.groups();lc=''
        if v.startswith(('"',"'",'`')) and len(v)>1 and v[-1]==v[0]:v=v[1:-1]
        else:
            mm=re.search(r'\s+[;#]',v)
            if mm:lc='#'+v[mm.end():].lstrip();v=v[:mm.start()].rstrip()
        val=scalar(v);val.line_comment=lc
        if comments:val.head='\n'.join(comments);comments=[]
        current.put(k,val)
    link(root);return root


def encode_ini(n,opts,unwrap):
    if n.kind=='scalar' and unwrap:return n.raw+'\n'
    if n.kind!='map':raise YQError('INI encoder supports only MappingNode at the root level, got '+('1' if n.kind=='seq' else '0'))
    lines=[]
    def section(obj):
        scalars=[(k,v) for k,v in obj.value if v.kind=='scalar']
        width=max([len(k.raw) for k,v in scalars]+[0]);out=[]
        for k,v in scalars:
            s=v.raw
            if '\n' in s:s='"""'+s+'"""'
            if v.head:out+=normalized_comment(v.head).splitlines()
            out.append(k.raw.ljust(width)+' = '+s)
        return out
    lines+=section(n)
    for k,v in n.value:
        if v.kind=='map':
            if lines:lines.append('')
            lines.append('['+k.raw+']');lines+=section(v)
    return '\n'.join(lines)+('\n' if lines else '')


def decode_xml(text,opts):
    attr=opts.get('xml_attribute_prefix','+@');content=opts.get('xml_content_name','+content');proc=opts.get('xml_proc_inst_prefix','+p_');direct=opts.get('xml_directive_name','+directive')
    declarations=[]
    def declaration(m):declarations.append((proc+'xml',m.group(1).strip()));return ''
    text=re.sub(r'<\?xml\s+(.*?)\?>',declaration,text,flags=re.S)
    directives=[]
    def directive(m):directives.append(m.group(1));return ''
    text=re.sub(r'<!([^>]*?)(?:\[[\s\S]*?\]\s*)?>',lambda m:m.group() if m.group().startswith('<!--') else directive(m),text)
    try:dom=xml.dom.minidom.parseString('<__yq_root__>'+text+'</__yq_root__>')
    except Exception as e:raise YQError('XML syntax error: '+str(e))
    root=mapping()
    if not opts.get('xml_skip_proc_inst'):
        for k,v in declarations:root.put(k,scalar(v))
    if not opts.get('xml_skip_directives'):
        for d in directives:root.put(direct,scalar(d))
    def add(obj,key,v):
        old=obj.get(key)
        if old is None:obj.put(key,v)
        elif old.kind=='seq':old.value.append(v);link(old)
        else:obj.put(key,sequence([old,v]))
    def name(s):return s if opts.get('xml_keep_namespace',True) else s.split(':')[-1]
    def element(el):
        texts=[];children=[];comments=[]
        for c in el.childNodes:
            if c.nodeType in (c.TEXT_NODE,c.CDATA_SECTION_NODE):
                if c.data.strip():texts.append(c.data.strip())
            elif c.nodeType==c.ELEMENT_NODE:
                v=element(c)
                if comments:v.head='\n'.join('# '+x for x in comments);comments=[]
                children.append((name(c.tagName),v))
            elif c.nodeType==c.COMMENT_NODE:comments.append(c.data.strip())
            elif c.nodeType==c.PROCESSING_INSTRUCTION_NODE and not opts.get('xml_skip_proc_inst'):children.append((proc+c.target,scalar(c.data)))
        attrs=[]
        if el.attributes:
            for i in range(el.attributes.length):
                a=el.attributes.item(i);attrs.append((attr+name(a.name),scalar(a.value)))
        if not children and not attrs:
            if not texts:return scalar(None,raw='')
            return scalar('\n'.join(texts))
        r=mapping()
        if texts:r.put(content,scalar(texts[0]) if len(texts)==1 else sequence([scalar(x) for x in texts]))
        for k,v in attrs:r.put(k,v)
        for k,v in children:add(r,k,v)
        if comments:r.foot='\n'.join('# '+x for x in comments)
        return r
    comments=[]
    for c in dom.documentElement.childNodes:
        if c.nodeType==c.ELEMENT_NODE:
            v=element(c)
            if comments:v.head='\n'.join('# '+x for x in comments);comments=[]
            add(root,name(c.tagName),v)
        elif c.nodeType==c.COMMENT_NODE:comments.append(c.data.strip())
        elif c.nodeType==c.PROCESSING_INSTRUCTION_NODE and not opts.get('xml_skip_proc_inst'):add(root,proc+c.target,scalar(c.data))
    link(root);return root


def encode_xml(n,opts):
    attr=opts.get('xml_attribute_prefix','+@');content=opts.get('xml_content_name','+content');proc=opts.get('xml_proc_inst_prefix','+p_');direct=opts.get('xml_directive_name','+directive')
    step=max(0,opts.get('indent',2))
    def esc(s):return xml_escape(s,{'"':'&#34;',"'":'&#39;','\r':'&#xD;'})
    def elem(key,v,depth):
        v=v.deref();sp=' '*(depth*step)
        if v.kind=='seq':return ''.join(elem(key,x,depth) for x in v.value)
        if key.startswith(proc):return sp+'<?'+key[len(proc):]+' '+v.raw+'?>\n'
        if key==direct:return sp+'<!'+v.raw+'>\n'
        attrs='';children=[];texts=[]
        if v.kind=='map':
            for k,x in v.value:
                if k.raw.startswith(attr):attrs+=' '+k.raw[len(attr):]+'="'+esc(x.raw)+'"'
                elif k.raw==content:
                    texts+=x.value if x.kind=='seq' else [x]
                else:children.append((k.raw,x))
        else:texts=[v]
        opening=sp+'<'+key+attrs+'>'
        if not children:return opening+''.join(esc(x.raw) for x in texts)+'</'+key+'>\n'
        ans=opening
        if texts:ans+=''.join(esc(x.raw) for x in texts)
        ans+='\n'
        for k,x in children:ans+=elem(k,x,depth+1)
        return ans+sp+'</'+key+'>\n'
    if n.kind=='scalar':return esc(n.raw)
    if n.kind=='seq':raise YQError('cannot encode array as XML without a key')
    return ''.join(elem(k.raw,v,0) for k,v in n.value)


def toml_scalar(n):
    if n.kind=='seq':return '['+', '.join(toml_scalar(x) for x in n.value)+']'
    if n.kind=='map':return '{ '+', '.join(k.raw+' = '+toml_scalar(v) for k,v in n.value)+' }'
    if n.tag=='!!str':return json.dumps(n.raw,ensure_ascii=False)
    if n.tag=='!!null':return '""'
    if n.tag=='!!bool':return n.raw.lower()
    return n.raw


def encode_toml(n,opts,unwrap):
    if n.kind=='scalar' and unwrap:return n.raw+'\n'
    if n.kind!='map':raise YQError('TOML encoder expects a mapping at the root level')
    lines=[]
    def key(k):return k if re.fullmatch(r'[A-Za-z0-9_-]+',k) else json.dumps(k,ensure_ascii=False)
    def visit(obj,path):
        nested=[]
        for k,v in obj.value:
            if v.kind=='map' and v.value:nested.append((k,v))
            elif v.kind=='seq' and v.value and all(x.kind=='map' for x in v.value):nested.append((k,v))
            else:
                if k.head:lines.extend(normalized_comment(k.head).splitlines())
                lines.append(key(k.raw)+' = '+toml_scalar(v))
        for k,v in nested:
            p=path+[key(k.raw)]
            if v.kind=='map':
                if lines:lines.append('')
                lines.append('['+'.'.join(p)+']');visit(v,p)
            else:
                for child in v.value:
                    if lines:lines.append('')
                    lines.append('[['+'.'.join(p)+']]');visit(child,p)
    visit(n,[]);return '\n'.join(lines)+('\n' if lines else '')


def decode_toml(text):
    # Basic TOML uses the same scalar forms as the YAML flow reader, with '=' in
    # inline tables and dotted, quoted table names.
    root=mapping();current=root;comments=[]
    def dotted(s):
        return [unquote(x.strip()) if x.strip().startswith(('"',"'")) else x.strip() for x in re.findall(r'"(?:\\.|[^"\\])*"|\x27[^\x27]*\x27|[^.]+',s)]
    def parseval(s):
        s=s.strip()
        if s.startswith('{'):
            # Replace assignment delimiters only outside quoted strings.
            s=re.sub(r'([\w.-]+)\s*=\s*',r'\1: ',s)
        n=FlowReader(s).read()
        for x in walk(n,True):x.style=''
        return n
    lines=text.splitlines();i=0
    while i<len(lines):
        s=lines[i].strip();i+=1
        if not s or s.startswith('#'):continue
        s,lc=uncomment(s)
        if s.startswith('['):
            arr=s.startswith('[[');body=s[2:-2] if arr else s[1:-1];path=dotted(body)
            cur=root
            for j,p in enumerate(path):
                child=cur.get(p)
                if j==len(path)-1 and arr:
                    if child is None:child=sequence();cur.put(p,child)
                    m=mapping();child.value.append(m);cur=m
                else:
                    if child is None:child=mapping();cur.put(p,child)
                    if child.kind=='seq':child=child.value[-1]
                    cur=child
            current=cur;continue
        if '=' not in s:raise YQError('toml: expected = after a key, but the document ends there')
        k,v=s.split('=',1);v=v.strip()
        if v.startswith(('"""',"'''")):
            q=v[:3];v=v[3:];content=''
            while q not in v and i<len(lines):content+=v+'\n';v=lines[i];i+=1
            content+=v.split(q,1)[0];val=scalar(content.lstrip('\n'))
        else:
            while v.startswith(('[','{')) and (v.count('[')>v.count(']') or v.count('{')>v.count('}')) and i<len(lines):v+=' '+uncomment(lines[i])[0];i+=1
            val=parseval(v)
        set_nested(current,dotted(k.strip()),val)
    link(root);return root


def encode_hcl(n,opts,unwrap):
    if n.kind=='scalar' and unwrap:return n.raw+'\n'
    def scalartext(v):
        if v.kind=='seq':return '['+', '.join(toml_scalar(x) for x in v.value)+']'
        if v.kind=='map':return '{}'
        if v.tag=='!!str':
            if v.style=='double' or not v.raw or '\n' in v.raw:return json.dumps(v.raw,ensure_ascii=False)
            return v.raw
        return v.raw
    step=max(0,opts.get('indent',2))
    def emit(obj,lev):
        lines=[]
        if obj.kind=='map':
            for k,v in obj.value:
                if v.kind=='map' and v.value:
                    lines.append(' '*(step*lev)+k.raw+' {');lines+=emit(v,lev+1);lines.append(' '*(step*lev)+'}')
                else:lines.append(' '*(step*lev)+k.raw+' = '+scalartext(v))
        elif obj.kind=='seq':lines=[scalartext(obj)]
        else:lines=[scalartext(obj)]
        return lines
    return '\n'.join(emit(n,0))+'\n'


def decode_hcl(text):
    # Block headers form nested maps; attributes have TOML-like values.
    tokens=re.findall(r'"(?:\\.|[^"\\])*"|#[^\n]*|//[^\n]*|[A-Za-z_][\w.-]*|[-+]?[0-9]+(?:\.[0-9]+)?|[^\s]',text)
    i=0
    def val():
        nonlocal i
        if i>=len(tokens):return scalar()
        t=tokens[i];i+=1
        if t=='[':
            xs=[]
            while i<len(tokens) and tokens[i]!=']':
                if tokens[i]==',':i+=1;continue
                xs.append(val())
            i+=1;return sequence(xs)
        if t=='{':return obj(True)
        if t.startswith('"'):return scalar(unquote(t))
        return resolve_plain(t)
    def obj(close=False):
        nonlocal i
        r=mapping()
        while i<len(tokens):
            if tokens[i].startswith(('#','//')):i+=1;continue
            if tokens[i]=='}':i+=1;break
            key=tokens[i];i+=1;key=unquote(key) if key.startswith('"') else key
            labels=[]
            while i<len(tokens) and tokens[i] not in ('=','{','}'):
                labels.append(unquote(tokens[i]));i+=1
            if i>=len(tokens):break
            op=tokens[i];i+=1
            v=obj(True) if op=='{' else val()
