'M':'no-colors','N':'no-doc','0':'nul-output','n':'null-input','o':'output-format','P':'prettyPrint',
'r':'unwrapScalar','s':'split-exp','v':'verbose','V':'version','c':'yaml-compact-seq-indent'}


class FlagError(YQError):pass


def parse_args(argv):
    opts={k.replace('-','_'):v for k,v in {**BOOLS,**STRINGS,'indent':2}.items()}
    opts['unwrap_set']=False;args=[];i=0;stop=False
    def setflag(name,val):
        key=name.replace('-','_')
        if name in BOOLS:
            if val is None:val=True
            elif str(val).lower() in ('true','1','t'):val=True
            elif str(val).lower() in ('false','0','f'):val=False
            else:raise FlagError('invalid argument "%s" for "--%s" flag: strconv.ParseBool: parsing "%s": invalid syntax'%(val,name,val))
        elif name=='indent':
            try:val=int(val)
            except Exception:raise FlagError('invalid argument "%s" for "-I, --indent" flag: strconv.ParseInt: parsing "%s": invalid syntax'%(val,val))
        elif name=='csv-separator' and len(val)!=1:
            raise FlagError('invalid argument "%s" for "--csv-separator" flag: must be exactly one character'%val)
        opts[key]=val
        if name=='unwrapScalar':opts['unwrap_set']=True
    while i<len(argv):
        a=argv[i];i+=1
        if stop or not a.startswith('-') or a=='-':args.append(a);continue
        if a=='--':stop=True;continue
        if a.startswith('--'):
            body=a[2:];name,eq,val=body.partition('=')
            if name not in BOOLS and name not in STRINGS and name!='indent':raise FlagError('unknown flag: --'+name)
            if not eq:
                if name in BOOLS:val=None
                elif i<len(argv):val=argv[i];i+=1
                else:raise FlagError('flag needs an argument: --'+name)
