                if j<len(body) and body[j]=='=':val=body[j+1:];j=len(body)
                else:val=None
            else:
                if j<len(body):val=body[j:];j=len(body);val=val[1:] if val.startswith('=') else val
                elif i<len(argv):val=argv[i];i+=1
                else:raise FlagError('flag needs an argument: -'+letter)
