        sys.stdout.write(ALL_HELP if sub in ('ea','eval-all') else EVAL_HELP if sub in ('e','eval') else ROOT_HELP)
        return 0
    if opts.get('help'):
        sys.stdout.write(ALL_HELP if command=='eval-all' else EVAL_HELP if explicit else ROOT_HELP);return 0
    if args and args[0]=='completion':return completion(args[1:])
